contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 value) public {
        require(to != address(0));
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        bool reverted;
        if (balBefore >= value) {
            c.transfer(to, value);
        }
        if (balBefore >= value) {
            reverted = false;
            assert(
                c.balanceOf(address(this)) == balBefore - value &&
                c.balanceOf(to) == value &&
                c.totalSupply() == totalBefore
            );
        } else {
            try c.transfer(to, value) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        require(amount > 0);
        // fund the test contract (the owner of c) with tokens via mint
        c.mintToken(address(this), amount);
        bool before = c.frozenAccount(recipient);
        require(!before);
        // freeze the recipient
        c.freezeAccount(recipient, true);
        bool revertedWhileFrozen;
        try c.transfer(recipient, amount) { revertedWhileFrozen = false; }
        catch { revertedWhileFrozen = true; }
        // unfreeze and retry
        c.freezeAccount(recipient, false);
        bool ok = c.transfer(recipient, amount);
        uint256 recipientBalance = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();
        assert(revertedWhileFrozen && ok && recipientBalance == amount && supplyAfter == amount);
    }
    receive() external payable {}
}

