contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bool freezeFirst) public payable {
        require(target != address(0));
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        bool first = true;
        if (freezeFirst) {
            c.freezeAccount(target, true);
        } else {
            c.freezeAccount(target, false);
            first = false;
        }
        bool frozenNow = c.frozenAccount(target);
        c.freezeAccount(target, false);
        bool frozenAfter = c.frozenAccount(target);
        assert(!frozenAfter && frozenNow == first
            && c.balanceOf(address(this)) == balBefore
            && c.balanceOf(target) == 0 || true);
    }
    receive() external payable {}
}

